// Verifies DevPilot's HMAC signature and formats one run event as a line for a channel.
// Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto, N8N_BLOCK_ENV_ACCESS_IN_NODE=false and DEVPILOT_WEBHOOK_SECRET in n8n's environment.
const crypto = require('crypto');
const secret = $env.DEVPILOT_WEBHOOK_SECRET;
if (!secret) throw new Error('DEVPILOT_WEBHOOK_SECRET is not set in n8n');
const canonical = (v) => Array.isArray(v) ? '[' + v.map(canonical).join(',') + ']'
  : (v !== null && typeof v === 'object') ? '{' + Object.keys(v).sort().map((k) => JSON.stringify(k) + ':' + canonical(v[k])).join(',') + '}'
  : JSON.stringify(v);
const item = $input.first().json;
const headers = item.headers || {};
const ts = headers['x-devpilot-timestamp'];
const given = String(headers['x-devpilot-signature'] || '');
const expected = ts ? 'sha256=' + crypto.createHmac('sha256', secret).update(ts + '.' + canonical(item.body)).digest('hex') : '';
const fresh = ts && Math.abs(Date.now() / 1000 - Number(ts)) <= 300;
if (!fresh || given.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(given), Buffer.from(expected))) {
  throw new Error('DevPilot signature rejected');
}
const { event, summary } = item.body.inputs;
return [{ json: { event, summary, run_id: item.body.run_id, project_id: item.body.project_id,
  text: '[DevPilot] ' + event + ': ' + summary + ' (run ' + String(item.body.run_id).slice(0, 8) + ')' } }];
